/**
 * Pure types for the rule-based assessment engine (phase 2 of docs/VISION_PLAN.md).
 * Everything here is generated by rules from the user's own uploaded text; nothing is produced by a model.
 */

import type { SourceLocation } from '../ingestion/types.ts';

export type QuestionType = 'definition' | 'cloze' | 'mcq' | 'truefalse' | 'numerical';

/** How a response is checked: exact option match, text similarity, or a number within a tolerance. */
export type GradingKind = 'exact' | 'short' | 'numeric';

export interface Question {
  /** Stable for the same type + prompt, so the same item is never shown twice. */
  id: string;
  type: QuestionType;
  grading: GradingKind;
  prompt: string;
  /** Multiple choice: the shown options; true/false: ['True', 'False']. */
  options?: string[];
  /** Canonical answer shown after grading (the correct option, the term, the definition, or the number). */
  answer: string;
  /** Other responses accepted as correct (e.g. the acronym of a term). */
  acceptable: string[];
  /** What short answers are compared against when it differs from `answer` (the definition body, not the whole sentence). */
  gradeText?: string;
  numeric?: { value: number; tolerance: number };
  /** The source sentence or the worked calculation, shown after answering. */
  explanation: string;
  termId?: string;
  /** The concept an attempt is recorded against. Null for practice-only items (e.g. numericals). */
  conceptId: string | null;
  sectionId: string | null;
  location: SourceLocation;
  /** "Generated from p. 12": generated items are always labelled as such. */
  label: string;
  practiceOnly: boolean;
}

export interface TermInput {
  termId: string;
  conceptId: string | null;
  term: string;
  definition: string | null;
  sectionId: string | null;
  location: SourceLocation;
}

/** Defined terms from the whole subject, the pool that wrong options are drawn from. */
export interface PoolEntry {
  term: string;
  definition: string;
}

export interface FormulaInput {
  text: string;
  sectionId: string | null;
  location: SourceLocation;
}

export interface GeneratorInput {
  terms: TermInput[];
  pool: PoolEntry[];
  formulas: FormulaInput[];
  seed: number;
  /** Types to rotate through for terms (numericals come from `formulas`). Default: all four term types. */
  types?: Array<Exclude<QuestionType, 'numerical'>>;
  /** Cap on numerical questions. Default 2. */
  maxNumerical?: number;
}

/** The seam for plugging in a local model later. Nothing depends on one. */
export interface QuestionGenerator {
  generate(input: GeneratorInput): Question[];
}

export interface Grade {
  correct: boolean;
  /** 0-1 similarity / confidence of the automatic verdict. */
  score: number;
  /** Short and numeric answers are graded automatically and must show an override step before being saved. */
  needsReview: boolean;
  method: 'exact' | 'edit-distance' | 'word-overlap' | 'numeric' | 'empty';
  detail: string;
}
